import numpy as np
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    den = (np.sum(h)**2) * np.max(L)
    return num / den if den > 0 else 0.0


def _negR(h):
    if np.any(h < 0):
        return 1e10
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    s = np.sum(h)
    if s <= 0:
        return 1e10
    M = np.max(L)
    if M <= 0:
        return 1e10
    return -num / (s * s * M)


def _smooth_obj(h, p):
    if np.any(h < 0):
        return 1e10
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    s = np.sum(h)
    if s <= 0:
        return 1e10
    M = np.sum(L**p)**(1.0 / p)
    if M <= 0:
        return 1e10
    return -num / (s * s * M)


def _pad_to(h, N):
    h = np.asarray(h, dtype=float)
    if len(h) >= N:
        return h[:N].copy()
    pad = N - len(h)
    left = pad // 2
    right = pad - left
    return np.concatenate((np.zeros(left), h, np.zeros(right)))


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds * 0.82

    candidates = []
    if start is not None:
        s = np.maximum(np.asarray(start, dtype=float), 0.0)
        if np.any(s > 0):
            candidates.append(s)

    # baseline triangle if nothing
    if not candidates:
        N = 101
        i = np.arange(N)
        candidates.append(1.0 + np.minimum(i, N - 1 - i).astype(float))

    best_h = candidates[0].copy()
    best_R = _R(best_h)

    for c in candidates:
        r = _R(c)
        if r > best_R:
            best_R = r
            best_h = c.copy()

    # Try resizing the best solution to nearby N values, then optimize.
    base = best_h.copy()
    Ns = sorted(set([len(base)] + [int(len(base) * f) for f in
                  (0.75, 0.9, 1.1, 1.25, 1.5, 2.0) if 20 <= int(len(base) * f) <= 50000]))

    def run_opt(h0, maxiter, ftol):
        bounds = [(0.0, None)] * len(h0)
        cur = h0.copy()
        curR = _R(cur)
        for p in (20.0, 40.0, 80.0):
            if time.process_time() - t0 > deadline:
                break
            try:
                res = minimize(_smooth_obj, cur, args=(p,), method='L-BFGS-B',
                               bounds=bounds,
                               options={'maxiter': maxiter, 'maxfun': 400000,
                                        'ftol': ftol, 'gtol': 1e-13})
                cand = np.maximum(res.x, 0.0)
                r = _R(cand)
                if r > curR:
                    curR = r
                    cur = cand
            except Exception:
                break
        return cur, curR

    cur, curR = run_opt(base, 3000, 1e-16)
    if curR > best_R:
        best_R, best_h = curR, cur

    # Try other N's
    for N in Ns:
        if N == len(best_h):
            continue
        if time.process_time() - t0 > deadline:
            break
        h0 = _pad_to(best_h, N)
        # rescale height by 1/N to keep magnitudes reasonable
        h0 = h0 * (len(best_h) / N)
        cur, curR = run_opt(h0, 1500, 1e-14)
        if curR > best_R:
            best_R, best_h = curR, cur

    # Local polish: add small random perturbations and refine
    rng = np.random.default_rng(12345)
    while time.process_time() - t0 < deadline:
        if len(best_h) == 0:
            break
        scale = 0.03 * (np.mean(best_h) + 1e-12)
        h0 = np.maximum(best_h + scale * rng.standard_normal(len(best_h)), 0.0)
        cur, curR = run_opt(h0, 800, 1e-14)
        if curR > best_R:
            best_R, best_h = curR, cur

    # final exact polish with a tight smooth max
    if time.process_time() - t0 < budget_seconds * 0.95:
        try:
            bounds = [(0.0, None)] * len(best_h)
            res = minimize(_smooth_obj, best_h, args=(200.0,), method='L-BFGS-B',
                           bounds=bounds,
                           options={'maxiter': 2000, 'maxfun': 200000,
                                    'ftol': 1e-16, 'gtol': 1e-14})
            cand = np.maximum(res.x, 0.0)
            r = _R(cand)
            if r > best_R:
                best_R, best_h = r, cand
        except Exception:
            pass

    print("final exact R = %.9f" % best_R)
    return best_h

