import numpy as np
from scipy.optimize import minimize


def _exact_R(h):
    h = np.asarray(h, dtype=float)
    if h.sum() <= 0:
        return 0.0
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    den = (np.sum(h)**2) * np.max(L)
    return num / den if den > 0 else 0.0


def _asymmetry(h):
    h = np.asarray(h, dtype=float)
    m = np.max(h)
    if m <= 0:
        return 0.0
    return float(np.max(np.abs(h - h[::-1])) / m)


def _num_den(h):
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    return num, L


def _objective_smooth(h, p, eps):
    if np.any(h < 0):
        return 1e10
    num, L = _num_den(h)
    s = np.sum(h)
    if s <= 0:
        return 1e10
    Lp = np.maximum(L, 0.0) + eps
    M = np.sum(Lp**p)**(1.0 / p)
    den = (s**2) * M
    if den <= 0:
        return 1e10
    return -num / den


def _objective_grad(h, p, eps):
    """Exact gradient of -num/den wrt h (smooth p-norm surrogate)."""
    h = np.asarray(h, dtype=float)
    if np.any(h < 0):
        return 1e10, np.zeros_like(h)
    num, L = _num_den(h)
    s = np.sum(h)
    if s <= 0:
        return 1e10, np.zeros_like(h)
    Lp = np.maximum(L, 0.0) + eps
    Sp = np.sum(Lp**p)
    if Sp <= 0:
        return 1e10, np.zeros_like(h)
    M = Sp**(1.0 / p)
    den = (s**2) * M
    if den <= 0:
        return 1e10, np.zeros_like(h)
    f = -num / den

    # d num / d L_k  (L includes endpoints 0)
    Lm = L[:-1]
    Lc = L[1:]
    dnum_dL = np.zeros_like(L)
    dnum_dL[:-1] += (2.0 * Lm + Lc) / 3.0
    dnum_dL[1:] += (Lm + 2.0 * Lc) / 3.0

    # dM/dL_k = Lp_k^(p-1) / M^(p-1)
    dM_dL = (Lp**(p - 1.0)) / (M**(p - 1.0))

    # L = [0, conv(h,h), 0]; interior indices 1..2N-1 map to conv index 0..2N-2
    # d(conv)/dh_i = 2*h[N-1-i] (for valid range), but easier via autoconv grad:
    # conv = h*h ; d conv_j / d h_i = h[j-i] + h[j-i]  (indices valid)
    # Use full gradient of num and M wrt conv, then fold.
    g_conv = (-(dnum_dL[1:-1]) / den) + (num / den**2) * (s**2) * dM_dL[1:-1]
    # g_conv is d(-num/den)/d(conv_j)
    # d(conv_j)/d h_i = h[j-i] + h[j-i]? Actually conv_j = sum_i h_i h_{j-i}
    # so d conv_j / d h_i = h_{j-i} + h_{j-i}? No: appears twice if i != j-i.
    # Standard: gradient of sum_j g_j conv_j wrt h = (g * h) + (g * h) reversed-ish.
    # conv = h*h, so d/dh (g . conv) = 2 * correlate(h, g) folded: use conv of g with h reversed.
    # g . (h*h) = sum_{i,k} g_{i+k} h_i h_k ; d/dh_i = 2 sum_k g_{i+k} h_k
    # = 2 * (g * h_rev)[...]. Implement directly:
    N = len(h)
    gfull = np.concatenate(([0.0], g_conv, [0.0]))  # length 2N+1, index j -> g at conv_j
    # d/dh_i = 2 * sum_k gfull[i+k] h_k  (i+k in 0..2N)
    grad_num = np.zeros(N)
    # correlate: for each i, sum_k gfull[i+k]*h_k
    # = conv of gfull with reversed h, take appropriate slice
    hrev = h[::-1]
    corr = np.convolve(gfull, hrev)  # length (2N+1)+N-1
    # index mapping: sum_k gfull[i+k] h_k = corr[(2N) - i]? derive:
    # convolve(gfull, hrev)[m] = sum_a gfull[a] hrev[m-a] = sum_a gfull[a] h[N-1-(m-a)]
    # want sum_k gfull[i+k] h_k => set a=i+k, h_k = h[N-1-(m-a)] => N-1-m+a = k => a = k+m-N+1
    # with a=i+k => i+k = k+m-N+1 => m = i+N-1. So corr[i+N-1].
    grad_num = 2.0 * corr[N - 1: N - 1 + N]

    # d den / d h: den = s^2 * M ; ds/dh_i = 1
    # d(-num/den)/dh = -(dnum/dh)/den + num/den^2 * dden/dh
    # dden/dh = 2 s M + s^2 * dM/dh ; dM/dh from g_conv part already included above via conv grad
    # We included num/den^2 * s^2 * dM/dconv in g_conv, so grad from that part is in grad_num.
    # Remaining: -dnum/dh/den  (already in grad_num as -(dnum)/den part) plus num/den^2 * 2 s M
    grad = grad_num + (num / den**2) * (2.0 * s * M) * np.ones(N)
    return f, grad


def _refine_sym(m, N, p, eps, maxiter, deadline):
    if time.process_time() > deadline:
        return m
    half = len(m)

    def build(mm):
        mm = np.maximum(mm, 0.0)
