        # fold gradient: g_full -> m
        if N % 2 == 0:
            gm = g[:half] + g[::-1][:half]
        else:
            gm = g[:half].copy()
            gm[:-1] += g[::-1][:half - 1]
        return f, gm

    bounds = [(0.0, None)] * half
    try:
