def _exact_R(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    den = (s * s) * np.max(L)
    return num / den if den > 0 else 0.0


def _components(h):
    """Return num, s, Lmax for exact R."""
    h = np.asarray(h, dtype=float)
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    return num, h.sum(), np.max(L)


def _smooth_and_grad(h, p, eps):
    """Return (objective, gradient) for smooth surrogate."""
    h = np.asarray(h, dtype=float)
    N = len(h)
    L = np.concatenate(([0.0], np.convolve(h, h), [0.0]))
    Lm1 = np.concatenate(([0.0], L[:-1]))
    Lp1 = np.concatenate((L[1:], [0.0]))
    c = (2.0 * L + Lm1 + Lp1) / 3.0
    dnum = 2.0 * np.convolve(h, c)[:2 * N - 1]

    s = np.sum(h)
    Lpos = np.maximum(L, 0.0) + eps
    Mp = np.sum(Lpos**p)
    M = Mp**(1.0 / p)
    dM_dL = Lpos**(p - 1.0) / (M**(p - 1.0))
    dM = 2.0 * np.convolve(h, dM_dL)[:2 * N - 1]

    num = np.sum(L[:-1]**2 + L[:-1] * L[1:] + L[1:]**2) / 3.0
    den = (s * s) * M
    if den <= 0 or s <= 0:
        return 1e10, np.zeros(N)
    obj = -num / den
    dden = 2.0 * s * M + (s * s) * dM
    g = -(dnum * den - num * dden) / (den * den)
    return obj, g


def _refine(h, p, eps, maxiter, deadline):
    if time.process_time() > deadline:
        return h
    N = len(h)
    try:
        res = minimize(
            _smooth_and_grad, h, args=(p, eps), method='L-BFGS-B',
            jac=True, bounds=[(0.0, None)] * N,
            options={'maxiter': maxiter, 'maxfun': 20 * maxiter,
