    n = len(h)
    # Smooth multiplicative perturbation (correlated noise) - better than iid
    noise = rng.standard_normal(n)
    # smooth with a small kernel to preserve structure
    k = max(1, n // 64)
    if k > 1:
        kernel = np.ones(k) / k
        noise = np.convolve(noise, kernel, mode='same')
    h = h * (1.0 + scale * noise)
    return np.maximum(h, 0.0)


