                    trial = _refine(trial, p, eps, 3000, deadline)
                R = _exact_R(trial)
                if R > best_R:
                    best_R = R
                    best_h = trial.copy()
                    h = trial.copy()
                    print("  perturb sc=%.3f R=%.9f N=%d" % (sc, best_R, len(h)))

    # Phase 4: final high-p polish
    if time.process_time() < deadline:
        h = best_h.copy()
        for p in (3000.0, 6000.0, 10000.0):
            if time.process_time() > deadline:
