def _resample(h, newN):
    """Resample step heights onto newN steps by piecewise-constant integration."""
    h = np.asarray(h, dtype=float)
    oldN = len(h)
    if oldN == newN:
        return h.copy()
    # cumulative integral of the step function
    cum = np.concatenate(([0.0], np.cumsum(h)))
    # new breakpoints in old units
    edges = np.linspace(0.0, oldN, newN + 1)
    vals = np.interp(edges, np.arange(oldN + 1), cum)
    out = np.diff(vals) * (oldN / newN)
    return np.maximum(out, 0.0)


