    g = np.zeros_like(L)
    g[:-1] += (2.0 * L[:-1] + L[1:]) / 3.0
    g[1:] += (2.0 * L[1:] + L[:-1]) / 3.0
    gc = g[1:-1]
    dnum_dh = 2.0 * np.correlate(gc, h, mode='valid')
    Lp = np.maximum(L, 0.0) + eps
    Lp_p = Lp**p
    Sp = np.sum(Lp_p)
    M = Sp**(1.0 / p)
    w = Lp**(p - 1)
    wc = w[1:-1]
    dM_dh = M**(1.0 - p) * 2.0 * np.correlate(wc, h, mode='valid')
    den = (s**2) * M
    if den <= 0:
        return 1e10, np.zeros_like(h)
    R = num / den
    dden_dh = 2.0 * s * M + (s**2) * dM_dh
    grad = -(dnum_dh * den - num * dden_dh) / (den**2)
    return -R, grad


def _mirror(v, N):
    m = (N + 1) // 2
    if N % 2 == 0:
        return np.concatenate((v, v[::-1]))
    else:
        return np.concatenate((v, v[-2::-1]))


def _fold_grad(g, N):
    m = (N + 1) // 2
    if N % 2 == 0:
        return g[:m] + g[m:][::-1]
    else:
        gv = g[:m].copy()
        gv[:m - 1] += g[m:][::-1]
        return gv


def _objective_grad_v(v, N, p, eps):
    h = _mirror(v, N)
    val, grad_h = _objective_grad_h(h, p, eps)
    if val >= 1e9:
        return val, np.zeros_like(v)
    return val, _fold_grad(grad_h, N)


def _refine_v(v, N, p, eps, maxiter, deadline):
    if time.process_time() > deadline:
        return v
    try:
        res = minimize(
            _objective_grad_v, v, args=(N, p, eps), method='L-BFGS-B',
            jac=True,
            options={'maxiter': maxiter, 'maxfun': 20 * maxiter,
                     'ftol': 1e-16, 'gtol': 1e-13},
        )
        return res.x
    except Exception:
        return v


def _split(h):
    return np.repeat(np.asarray(h, dtype=float), 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        h0 = np.maximum(h0, 0.0)
    else:
        N = 101
        i = np.arange(N)
        h0 = 1.0 + np.minimum(i, N - 1 - i).astype(float)

    best_h = h0.copy()
    best_R = _exact_R(best_h)
    print("init R = %.9f, N=%d" % (best_R, len(best_h)))

    # symmetrize and work on half profile
    hs = 0.5 * (h0 + h0[::-1])
    m = (len(hs) + 1) // 2
    v = np.maximum(hs[:m].copy(), 0.0)
    N = len(hs)
    eps = 1e-7

    # Refine at current resolution with increasing p, then split-refine.
    # Splitting is R-invariant but lets the profile sharpen at finer scale.
    for rnd in range(6):
        if time.process_time() > deadline:
            break
        for p in (1000.0, 3000.0, 10000.0, 30000.0):
            if time.process_time() > deadline:
                break
            v = _refine_v(v, N, p, eps, 3000, deadline)
            h = _mirror(v, N)
            R = _exact_R(h)
            if R > best_R:
                best_R = R
                best_h = h.copy()
            print("  rnd=%d p=%.0f R=%.9f N=%d" % (rnd, p, best_R, N))

        if N * 2 > 50000:
            break
        # split: refine at doubled resolution
        h = _mirror(v, N)
        h = _split(h)
        N = len(h)
        m = (N + 1) // 2
        v = h[:m].copy()
        print("split N=%d" % N)

    print("final exact R = %.9f, N=%d" % (best_R, len(best_h)))
    return best_h
